#!/usr/bin/env python3
import pathlib,json,hashlib,shutil,difflib,subprocess,importlib.util
H=pathlib.Path(__file__).resolve().parent;C=json.loads((H/'SOURCE_CONTRACT.json').read_text());D=pathlib.Path(C['destination']['candidate_overlay_root']);O=pathlib.Path(C['destination']['existing_root']);RAW=pathlib.Path('/mnt/extdrive/workdir/htt_open_data/r36_science_synthesis_actual')
