write(H/'ARTIFACT_MANIFEST.json',{'schema':'htt.r36.science_synthesis_artifacts/1','task_id':C['task_id'],'packet_id':C['packet_id'],'input_identity':C['input_identity'],'source_contract_sha256':sha(H/'SOURCE_CONTRACT.json'),'artifacts':artifacts,'acceptance_met':False,'scientific_admission':'HOLD_PENDING_AUTHOR_CONSUMPTION_AND_FRESH_REVIEW'})
